public java.util.Map<Character, Integer> charFrequency(String s) {
    java.util.Map<Character, Integer> freq = new java.util.HashMap<>();
    for (char ch : s.toCharArray()) {
        freq.put(ch, freq.getOrDefault(ch, 0) + 1);
    }
    return freq;
}

